-- 00009_offers_bookings.sql
-- Migration 00009 — offers lifecycle + atomic bookings + venue claims.
--
-- Offers: draft -> live -> ended/cancelled. Only VERIFIED businesses may
-- publish (guard_offer_publish); drafts are free to create.
-- Bookings: create_booking() locks the offer row so concurrent bookings for
-- the same slot serialize — capacity can never be overbooked. Capacity is
-- derived (sum of party_size over pending/confirmed), so cancellations free
-- seats automatically.

alter table offers
  add column if not exists venue_id uuid references venues(id),
  add column if not exists price_cents int check (price_cents is null or price_cents >= 0),
  add column if not exists slot_capacity int not null default 10
    check (slot_capacity > 0);

alter table offers drop constraint if exists offers_status_check;
alter table offers add constraint offers_status_check
  check (status in ('draft', 'live', 'ended', 'cancelled'));

-- Server-side publish gate: only verified businesses go live.
create or replace function guard_offer_publish() returns trigger as $$
declare
  v_verification text;
begin
  if new.status = 'live' and (tg_op = 'INSERT' or old.status is distinct from 'live') then
    select verification_status into v_verification from profiles where id = new.business_id;
    if v_verification is distinct from 'verified' then
      raise exception 'only verified businesses can publish offers';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_guard_offer_publish on offers;
create trigger trg_guard_offer_publish
  before insert or update of status on offers
  for each row execute function guard_offer_publish();

-- Atomic booking with per-slot capacity. Slots are exact timestamps sent by
-- the client (minute precision); the offer window bounds them.
create or replace function create_booking(
  p_offer_id uuid,
  p_slot timestamptz,
  p_party_size int
) returns json as $$
declare
  v_business uuid;
  v_status text;
  v_starts timestamptz;
  v_ends timestamptz;
  v_capacity int;
  v_taken int;
  v_customer uuid;
  v_booking_id uuid;
begin
  v_customer := auth.uid();
  if v_customer is null then
    raise exception 'not authenticated';
  end if;
  if p_party_size < 1 or p_party_size > 50 then
    raise exception 'party size must be between 1 and 50';
  end if;

  -- Serialize concurrent bookings for this offer.
  select business_id, status, starts_at, ends_at, slot_capacity
    into v_business, v_status, v_starts, v_ends, v_capacity
  from offers where id = p_offer_id for update;
  if not found then
    raise exception 'offer not found';
  end if;
  if v_status != 'live' then
    raise exception 'offer is not live';
  end if;
  if v_business = v_customer then
    raise exception 'cannot book your own offer';
  end if;
  if p_slot < v_starts or p_slot > v_ends then
    raise exception 'slot is outside the offer window';
  end if;
  if p_slot <= now() then
    raise exception 'slot must be in the future';
  end if;

  select coalesce(sum(party_size), 0) into v_taken from bookings
  where offer_id = p_offer_id and slot = p_slot and status in ('pending', 'confirmed');
  if v_taken + p_party_size > v_capacity then
    raise exception 'not enough seats left for this slot';
  end if;

  insert into bookings (offer_id, customer_id, slot, party_size, status)
  values (p_offer_id, v_customer, p_slot, p_party_size, 'pending')
  returning id into v_booking_id;

  return json_build_object(
    'booking_id', v_booking_id,
    'seats_left', v_capacity - v_taken - p_party_size
  );
end;
$$ language plpgsql security definer set search_path = public;

-- Business claims an unclaimed venue (sets business_id). Business accounts only.
create or replace function claim_venue(p_venue_id uuid) returns void as $$
declare
  v_acct text;
begin
  select account_type into v_acct from profiles where id = auth.uid();
  if v_acct is distinct from 'business' then
    raise exception 'only business accounts can claim venues';
  end if;
  update venues set business_id = auth.uid()
  where id = p_venue_id and business_id is null;
  if not found then
    raise exception 'venue not found or already claimed';
  end if;
end;
$$ language plpgsql security definer set search_path = public;

-- Business view: bookings across my offers with customer + offer context.
create or replace view business_bookings as
select
  b.*,
  o.business_id,
  o.title as offer_title,
  c.display_name as customer_name
from bookings b
join offers o on o.id = b.offer_id
join profiles c on c.id = b.customer_id;

alter view business_bookings set (security_invoker = true);
grant select on business_bookings to authenticated;


-- 00010_chat_notifications.sql
-- Migration 00010 — 1:1 chat, notifications, push tokens.
--
-- Chat is AUTHORIZED: a conversation can only be opened between a post
-- author and an approved participant (post scope), or between a booking's
-- customer and business (booking scope). get_or_create_conversation()
-- enforces this server-side; there is no direct client insert path.
--
-- Notifications are written by security-definer triggers on join_requests,
-- bookings and messages. Remote push delivery goes through the
-- `send-push` edge function (supabase/functions/send-push), invoked by the
-- app after the triggering action; see its README.

-- ── Conversations & messages ──────────────────────────────

-- On upgrades from the original schema, archive legacy records intact.
-- Already-applied 00010 installations must NOT replay this migration.
alter table messages rename to legacy_messages;
alter table threads rename to legacy_threads;
alter table notifications rename to legacy_notifications;
revoke all on legacy_messages, legacy_threads, legacy_notifications from anon, authenticated;

create table conversations (
  id uuid primary key default gen_random_uuid(),
  post_id uuid references posts(id) on delete cascade,
  booking_id uuid references bookings(id) on delete cascade,
  user_a uuid not null references profiles(id) on delete cascade,
  user_b uuid not null references profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  check (post_id is not null or booking_id is not null),
  check (user_a != user_b)
);

-- One conversation per (context, unordered pair).
create unique index conv_post_unique
  on conversations (post_id, user_a, user_b) where booking_id is null;
create unique index conv_booking_unique
  on conversations (booking_id, user_a, user_b) where post_id is null;

create table messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references conversations(id) on delete cascade,
  sender_id uuid not null references profiles(id) on delete cascade,
  body text not null check (char_length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);
create index messages_conv_idx on messages (conversation_id, created_at);

create table conversation_reads (
  conversation_id uuid not null references conversations(id) on delete cascade,
  user_id uuid not null references profiles(id) on delete cascade,
  last_read_at timestamptz not null default now(),
  primary key (conversation_id, user_id)
);

alter table conversations enable row level security;
alter table messages enable row level security;
alter table conversation_reads enable row level security;

create policy "members read conversations" on conversations for select
  using (auth.uid() = user_a or auth.uid() = user_b);

create policy "members read messages" on messages for select
  using (exists (
    select 1 from conversations c
    where c.id = messages.conversation_id
      and (c.user_a = auth.uid() or c.user_b = auth.uid())
  ));

create policy "members send messages" on messages for insert
  with check (
    sender_id = auth.uid() and exists (
      select 1 from conversations c
      where c.id = messages.conversation_id
        and (c.user_a = auth.uid() or c.user_b = auth.uid())
    )
  );

create policy "users manage own reads" on conversation_reads for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- ── Authorized conversation creation ─────────────────────

create or replace function get_or_create_conversation(
  p_other_user uuid,
  p_post_id uuid default null,
  p_booking_id uuid default null
) returns uuid as $$
declare
  v_me uuid := auth.uid();
  v_a uuid;
  v_b uuid;
  v_conv uuid;
  v_author uuid;
  v_customer uuid;
  v_business uuid;
begin
  if v_me is null then
    raise exception 'not authenticated';
  end if;
  if p_other_user = v_me then
    raise exception 'cannot chat with yourself';
  end if;
  if not exists (select 1 from profiles where id = p_other_user) then
    raise exception 'user not found';
  end if;
  if (p_post_id is null) = (p_booking_id is null) then
    raise exception 'provide exactly one of post_id or booking_id';
  end if;

  if p_post_id is not null then
    -- post scope: author <-> approved participant, either direction
    select author_id into v_author from posts where id = p_post_id;
    if not found then
      raise exception 'post not found';
    end if;
    if not (
      (v_author = v_me and exists (
        select 1 from join_requests
        where post_id = p_post_id and requester_id = p_other_user and status = 'approved'))
      or
      (v_author = p_other_user and exists (
        select 1 from join_requests
        where post_id = p_post_id and requester_id = v_me and status = 'approved'))
    ) then
      raise exception 'chat not allowed for this post';
    end if;
  else
    -- booking scope: customer <-> business, either direction
    select b.customer_id, o.business_id into v_customer, v_business
    from bookings b join offers o on o.id = b.offer_id
    where b.id = p_booking_id;
    if not found then
      raise exception 'booking not found';
    end if;
    if not ((v_customer = v_me and v_business = p_other_user)
         or (v_business = v_me and v_customer = p_other_user)) then
      raise exception 'chat not allowed for this booking';
    end if;
  end if;

  -- canonical member ordering so the unique index dedupes both directions
  v_a := least(v_me, p_other_user);
  v_b := greatest(v_me, p_other_user);

  select c.id into v_conv from conversations c
  where c.post_id is not distinct from p_post_id
    and c.booking_id is not distinct from p_booking_id
    and c.user_a = v_a and c.user_b = v_b;

  if v_conv is null then
    begin
      insert into conversations (post_id, booking_id, user_a, user_b)
      values (p_post_id, p_booking_id, v_a, v_b)
      returning id into v_conv;
    exception when unique_violation then
      -- lost a race with another creator; fetch the winner
      select c.id into v_conv from conversations c
      where c.post_id is not distinct from p_post_id
        and c.booking_id is not distinct from p_booking_id
        and c.user_a = v_a and c.user_b = v_b;
    end;
  end if;
  return v_conv;
end;
$$ language plpgsql security definer set search_path = public;

-- ── Chat list with unread counts ──────────────────────────

create or replace function list_my_conversations() returns json as $$
  select coalesce(json_agg(row_to_json(t) order by t.last_at desc nulls last), '[]'::json)
  from (
    select
      c.id,
      case when c.user_a = auth.uid() then c.user_b else c.user_a end as other_user_id,
      p.display_name as other_name,
      c.post_id,
      c.booking_id,
      coalesce(post.title, offer.title) as context_title,
      (select m.body from messages m
        where m.conversation_id = c.id order by m.created_at desc limit 1) as last_body,
      (select m.created_at from messages m
        where m.conversation_id = c.id order by m.created_at desc limit 1) as last_at,
      (select count(*) from messages m
        where m.conversation_id = c.id
          and m.sender_id != auth.uid()
          and m.created_at > coalesce((
            select r.last_read_at from conversation_reads r
            where r.conversation_id = c.id and r.user_id = auth.uid()
          ), '1970-01-01'::timestamptz)) as unread_count
    from conversations c
    join profiles p
      on p.id = case when c.user_a = auth.uid() then c.user_b else c.user_a end
    left join posts post on post.id = c.post_id
    left join bookings b on b.id = c.booking_id
    left join offers offer on offer.id = b.offer_id
    where c.user_a = auth.uid() or c.user_b = auth.uid()
  ) t;
$$ language sql security definer set search_path = public;

create or replace function mark_conversation_read(p_conversation_id uuid) returns void as $$
begin
  if not exists (
    select 1 from conversations
    where id = p_conversation_id
      and (user_a = auth.uid() or user_b = auth.uid())
  ) then
    raise exception 'not a conversation member';
  end if;
  insert into conversation_reads (conversation_id, user_id, last_read_at)
  values (p_conversation_id, auth.uid(), now())
  on conflict (conversation_id, user_id) do update set last_read_at = now();
end;
$$ language plpgsql security definer set search_path = public;

-- ── Push tokens ───────────────────────────────────────────

create table push_tokens (
  user_id uuid not null references profiles(id) on delete cascade,
  token text not null,
  platform text not null check (platform in ('android', 'ios')),
  updated_at timestamptz not null default now(),
  primary key (user_id, token)
);

alter table push_tokens enable row level security;

create policy "users manage own tokens" on push_tokens for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- ── In-app notifications ──────────────────────────────────

create table notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles(id) on delete cascade,
  kind text not null check (kind in (
    'join_request', 'request_approved', 'request_declined',
    'booking', 'booking_confirmed', 'booking_cancelled', 'message'
  )),
  title text not null,
  body text not null,
  ref_id uuid,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on notifications (user_id, created_at desc);

alter table notifications enable row level security;

create policy "users read own notifications" on notifications for select
  using (auth.uid() = user_id);

create policy "users mark own notifications read" on notifications for update
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Event -> notification writers (security definer: only triggers write).

create or replace function notify_join_request() returns trigger as $$
declare
  v_title text;
  v_body text;
  v_user uuid;
  v_kind text;
begin
  if tg_op = 'INSERT' then
    v_kind := 'join_request';
    select p.author_id into v_user from posts p where p.id = new.post_id;
    select 'New join request',
           pr.display_name || ' wants to join "' || p.title || '"'
      into v_title, v_body
    from profiles pr, posts p
    where pr.id = new.requester_id and p.id = new.post_id;
  elsif tg_op = 'UPDATE' and new.status = 'approved' and old.status is distinct from 'approved' then
    v_kind := 'request_approved';
    v_user := new.requester_id;
    select 'Request approved', 'You''re in! "' || p.title || '"'
      into v_title, v_body from posts p where p.id = new.post_id;
  elsif tg_op = 'UPDATE' and new.status = 'declined' and old.status is distinct from 'declined' then
    v_kind := 'request_declined';
    v_user := new.requester_id;
    select 'Request declined', '"' || p.title || '" didn''t work out this time'
      into v_title, v_body from posts p where p.id = new.post_id;
  else
    return new;
  end if;

  insert into notifications (user_id, kind, title, body, ref_id)
  values (v_user, v_kind, v_title, v_body, new.post_id);
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_join_request on join_requests;
create trigger trg_notify_join_request
  after insert or update of status on join_requests
  for each row execute function notify_join_request();

create or replace function notify_booking() returns trigger as $$
declare
  v_title text;
  v_body text;
  v_user uuid;
  v_kind text;
begin
  if tg_op = 'INSERT' then
    v_kind := 'booking';
    select o.business_id into v_user from offers o where o.id = new.offer_id;
    select 'New booking',
           pr.display_name || ' booked ' || new.party_size || ' seat(s) for "' || o.title || '"'
      into v_title, v_body
    from profiles pr, offers o
    where pr.id = new.customer_id and o.id = new.offer_id;
  elsif tg_op = 'UPDATE' and new.status = 'confirmed' and old.status is distinct from 'confirmed' then
    v_kind := 'booking_confirmed';
    v_user := new.customer_id;
    select 'Booking confirmed', '"' || o.title || '" — see you there'
      into v_title, v_body from offers o where o.id = new.offer_id;
  elsif tg_op = 'UPDATE' and new.status = 'cancelled' and old.status is distinct from 'cancelled' then
    v_kind := 'booking_cancelled';
    -- notify the other party, whoever cancelled
    select case when new.customer_id = auth.uid() then o.business_id else new.customer_id end
      into v_user from offers o where o.id = new.offer_id;
    select 'Booking cancelled', '"' || o.title || '" was cancelled'
      into v_title, v_body from offers o where o.id = new.offer_id;
  else
    return new;
  end if;

  insert into notifications (user_id, kind, title, body, ref_id)
  values (v_user, v_kind, v_title, v_body, new.offer_id);
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_booking on bookings;
create trigger trg_notify_booking
  after insert or update of status on bookings
  for each row execute function notify_booking();

create or replace function notify_message() returns trigger as $$
declare
  v_user uuid;
  v_name text;
begin
  select case when c.user_a = new.sender_id then c.user_b else c.user_a end
    into v_user from conversations c where c.id = new.conversation_id;
  select display_name into v_name from profiles where id = new.sender_id;
  insert into notifications (user_id, kind, title, body, ref_id)
  values (v_user, 'message', 'Message from ' || coalesce(v_name, 'someone'),
          left(new.body, 140), new.conversation_id);
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_message on messages;
create trigger trg_notify_message
  after insert on messages
  for each row execute function notify_message();


-- 00011_core_hardening.sql
-- Forward migration: existing rows are preserved. Apply after 00010.

-- Client access to private profile columns is through get_my_profile only.
revoke select, insert, update, delete on profiles from anon, authenticated;
grant select (id, display_name, avatar_url, bio, business_name, verification_status) on profiles to anon, authenticated;
grant update (display_name, avatar_url, bio, interests, business_name, business_details, onboarding_completed) on profiles to authenticated;
alter table profiles add column if not exists role_selected boolean not null default true;
-- Existing onboarded accounts retain their role. Incomplete accounts can confirm it.
update profiles set role_selected = onboarding_completed;
create or replace function handle_new_user() returns trigger as $$
begin
  insert into public.profiles (id, account_type, display_name, role_selected)
  values (new.id,
    case when new.raw_user_meta_data ->> 'account_type' = 'business' then 'business' else 'personal' end,
    coalesce(new.raw_user_meta_data ->> 'display_name', new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1), 'user'),
    coalesce(new.raw_user_meta_data ->> 'account_type' in ('personal', 'business'),false));
  return new;
end;
$$ language plpgsql security definer set search_path = public;
-- NULL metadata is normalized explicitly.
create or replace function get_my_profile() returns jsonb as $$
  select to_jsonb(p) from profiles p where p.id = auth.uid();
$$ language sql security definer set search_path = public;
create or replace function select_account_type(p_account_type text) returns void as $$
declare p profiles;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_account_type is null or p_account_type not in ('personal','business') then raise exception 'invalid account type'; end if;
  select * into p from profiles where id = auth.uid() for update;
  if not found then raise exception 'profile not found'; end if;
  if p.onboarding_completed or p.role_selected then
    if p.account_type <> p_account_type then raise exception 'account type is already selected'; end if;
    return;
  end if;
  if p.account_type=p_account_type then update profiles set role_selected=true where id=p.id;return;end if;
  if p.verification_status <> 'unverified' or exists(select 1 from offers where business_id = p.id)
    or exists(select 1 from posts where author_id = p.id) then raise exception 'account type cannot change'; end if;
  update profiles set account_type = p_account_type, role_selected = true where id = p.id;
end;
$$ language plpgsql security definer set search_path = public;
-- Private proof submission is an authorized RPC, not a client status update.
create or replace function submit_verification(p_path text) returns void as $$
declare p profiles;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select * into p from profiles where id = auth.uid() for update;
  if p.account_type <> 'business' or p.verification_status not in ('unverified','rejected') then raise exception 'verification cannot be submitted'; end if;
  if p_path is null or split_part(p_path, '/', 1) <> auth.uid()::text or not exists(
    select 1 from storage.objects where bucket_id = 'verification_docs' and name = p_path
  ) then raise exception 'upload your proof document first'; end if;
  update profiles set verification_doc_path = p_path, verification_status = 'pending' where id = p.id;
end;
$$ language plpgsql security definer set search_path = public;
-- Grants protect role and verification; owner onboarding writes are validated.
create or replace function protect_profile_fields() returns trigger as $$
begin
  if current_user in ('anon','authenticated') then
    if new.account_type is distinct from old.account_type or new.role_selected is distinct from old.role_selected
      or new.verification_status is distinct from old.verification_status
      or new.verification_doc_path is distinct from old.verification_doc_path then raise exception 'protected profile field'; end if;
    if new.onboarding_completed and (not new.role_selected or char_length(btrim(new.display_name)) < 2
      or (new.account_type = 'business' and (char_length(btrim(coalesce(new.business_name,''))) < 2
        or coalesce(new.business_details->>'category','') = '' or coalesce(new.business_details->>'area','') = '')))
      then raise exception 'complete your profile before onboarding'; end if;
  end if;
  return new;
end;
$$ language plpgsql;
-- Seeded venue ownership must be reviewed by an administrator.
create or replace function claim_venue(p_venue_id uuid) returns void as $$
begin raise exception 'Venue ownership requires administrator review. Submit your business proof first.'; end;
$$ language plpgsql security definer set search_path = public;
revoke insert, update, delete on venues from anon, authenticated;

-- Join requests are mutated only through locked, authorized RPCs.
revoke insert, update, delete on join_requests from anon, authenticated;
create or replace function request_join(p_post_id uuid) returns jsonb as $$
declare p posts; r join_requests;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from profiles where id = auth.uid() and account_type = 'personal' and onboarding_completed) then raise exception 'personal onboarding required'; end if;
  select * into p from posts where id = p_post_id for update;
  if not found or p.author_id = auth.uid() then raise exception 'post not found or cannot join your own post'; end if;
  if p.status <> 'open' or coalesce(p.expires_at,p.starts_at) <= now() or p.starts_at <= now() then raise exception 'post is closed or expired'; end if;
  if (select count(*) from join_requests where post_id=p.id and status='approved') >= p.vacancies then raise exception 'post is full'; end if;
  select * into r from join_requests where post_id=p.id and requester_id=auth.uid() for update;
  if found and r.status in ('pending','approved') then raise exception 'you already requested or joined this post'; end if;
  if r.id is null then
    insert into join_requests(post_id,requester_id,status) values(p.id,auth.uid(),'pending') returning * into r;
  else
    update join_requests set status='pending',created_at=now() where id=r.id returning * into r;
  end if;
  return to_jsonb(r);
end;
$$ language plpgsql security definer set search_path=public;
-- Post-first lock ordering is shared by request, approval, withdrawal and host edits.
create or replace function approve_join_request(p_request_id uuid) returns json as $$
declare p posts; r join_requests; pid uuid; taken int;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select post_id into pid from join_requests where id=p_request_id;
  select * into p from posts where id=pid for update;
  if not found or p.author_id is distinct from auth.uid() then raise exception 'only the host can approve requests'; end if;
  select * into r from join_requests where id=p_request_id and post_id=p.id for update;
  if not found or r.status <> 'pending' then raise exception 'request is not pending'; end if;
  if r.requester_id=p.author_id then raise exception 'cannot join your own post'; end if;
  if p.status <> 'open' or coalesce(p.expires_at,p.starts_at)<=now() or p.starts_at<=now() then raise exception 'post is closed or expired'; end if;
  select count(*) into taken from join_requests where post_id=p.id and status='approved';
  if taken>=p.vacancies then raise exception 'post is full'; end if;
  update join_requests set status='approved' where id=r.id;
  if taken+1>=p.vacancies then update posts set status='closed' where id=p.id; end if;
  return json_build_object('spots_left',p.vacancies-taken-1,'post_closed',taken+1>=p.vacancies);
end;
$$ language plpgsql security definer set search_path=public;
create or replace function withdraw_join_request(p_request_id uuid) returns void as $$
declare p posts; r join_requests; pid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select post_id into pid from join_requests where id=p_request_id;
  select * into p from posts where id=pid for update;
  select * into r from join_requests where id=p_request_id for update;
  if not found or r.requester_id is distinct from auth.uid() then raise exception 'only the participant can withdraw'; end if;
  if r.status='withdrawn' then return; end if;
  if r.status not in ('pending','approved') then raise exception 'request cannot be withdrawn'; end if;
  update join_requests set status='withdrawn' where id=r.id;
end;
$$ language plpgsql security definer set search_path=public;
create or replace function decline_join_request(p_request_id uuid) returns void as $$
declare p posts; r join_requests; pid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select post_id into pid from join_requests where id=p_request_id;
  select * into p from posts where id=pid for update;
  if not found or p.author_id is distinct from auth.uid() then raise exception 'only the host can decline'; end if;
  select * into r from join_requests where id=p_request_id for update;
  if not found or r.status <> 'pending' then raise exception 'request is not pending'; end if;
  update join_requests set status='declined' where id=r.id;
end;
$$ language plpgsql security definer set search_path=public;
create or replace function reopen_post_if_space() returns trigger as $$
declare p posts;
begin
  if old.status <> 'approved' then return coalesce(new,old); end if;
  if tg_op='UPDATE' and new.status='approved' then return new; end if;
  select * into p from posts where id=old.post_id for update;
  if p.status='closed' and coalesce(p.expires_at,p.starts_at)>now() and p.starts_at>now()
    and (select count(*) from join_requests where post_id=p.id and status='approved')<p.vacancies then
    update posts set status='open' where id=p.id;
  end if;
  return coalesce(new,old);
end;
$$ language plpgsql security definer set search_path=public;
-- Counts expose only a number; private participant rows still use RLS.
create or replace function approved_join_count(p_post_id uuid) returns int as $$
  select count(*)::int from join_requests where post_id=p_post_id and status='approved';
$$ language sql stable security definer set search_path=public;
create or replace view post_cards with (security_invoker=true) as
select p.*,pr.display_name as author_name,approved_join_count(p.id) as approved_count
from posts p join profiles pr on pr.id=p.author_id;

-- Protect every post mutation, including status-only writes and ownership.
revoke update, delete on posts from anon,authenticated;
grant update(title,description,venue_id,venue_name,starts_at,expires_at,vacancies,cost_cents,tags) on posts to authenticated;
create or replace function guard_post_edit() returns trigger as $$
declare taken int;
begin
  if tg_op='UPDATE' then
    if new.author_id is distinct from old.author_id then raise exception 'post ownership cannot change'; end if;
    if current_user='authenticated' then
      if old.author_id is distinct from auth.uid() or old.status<>'open' then raise exception 'only the host can edit open posts'; end if;
    end if;
    -- Lifecycle RPCs may update status without revalidating old form fields.
    if row(new.title,new.description,new.venue_id,new.venue_name,new.starts_at,new.expires_at,new.vacancies,new.cost_cents,new.tags)
      is not distinct from row(old.title,old.description,old.venue_id,old.venue_name,old.starts_at,old.expires_at,old.vacancies,old.cost_cents,old.tags) then return new; end if;
  end if;
  if char_length(btrim(new.title)) not between 4 and 80 or char_length(btrim(new.description)) not between 10 and 1000
    or new.vacancies not between 1 and 100 or new.starts_at<=now()+interval '15 minutes'
    or (new.expires_at is not null and (new.expires_at<=now() or new.expires_at>=new.starts_at)) then raise exception 'invalid post details'; end if;
  if current_user='authenticated' and not exists(select 1 from profiles where id=auth.uid() and account_type='personal' and onboarding_completed) then raise exception 'personal onboarding required'; end if;
  select count(*) into taken from join_requests where post_id=new.id and status='approved';
  if new.vacancies<taken then raise exception 'vacancies cannot be below approved count'; end if;
  if taken>=new.vacancies then new.status='closed'; end if;
  return new;
end;
$$ language plpgsql;
drop trigger if exists trg_guard_post_edit on posts;
create trigger trg_guard_post_edit before insert or update on posts for each row execute function guard_post_edit();
create or replace function cancel_post(p_post_id uuid) returns void as $$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  update posts set status='cancelled' where id=p_post_id and author_id=auth.uid() and status in ('open','closed') and starts_at>now();
  if not found then raise exception 'post not found, already cancelled, or not yours'; end if;
end;
$$ language plpgsql security definer set search_path=public;
create or replace function close_expired_posts() returns int as $$
declare n int;
begin
  update posts set status='closed' where status='open' and coalesce(expires_at,starts_at)<=now();
  get diagnostics n=row_count;return n;
end;
$$ language plpgsql security definer set search_path=public;

-- Emit a public post change when private participation changes. No participant data leaks.
create or replace function refresh_post_capacity_event() returns trigger as $$
begin
 if (tg_op='INSERT' and new.status='approved') or
   (tg_op='UPDATE' and (new.status='approved' or old.status='approved')) then
   update posts set status=status where id=new.post_id;
 elsif tg_op='DELETE' and old.status='approved' then update posts set status=status where id=old.post_id; end if;
 return coalesce(new,old);
end;
$$ language plpgsql security definer set search_path=public;
create trigger trg_refresh_post_capacity_event after insert or update of status or delete on join_requests
 for each row execute function refresh_post_capacity_event();

-- Remove raw booking mutation paths, including customer self-confirmation.
revoke insert,update,delete on bookings from anon,authenticated;
create or replace function change_booking_status(p_booking_id uuid,p_status text) returns void as $$
declare b bookings; o offers; oid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select offer_id into oid from bookings where id=p_booking_id;
  select * into o from offers where id=oid for update;
  select * into b from bookings where id=p_booking_id for update;
  if not found or (b.customer_id is distinct from auth.uid() and o.business_id is distinct from auth.uid()) then raise exception 'not your booking'; end if;
  if p_status='confirmed' then
    if o.business_id is distinct from auth.uid() then raise exception 'only the business can confirm'; end if;
    if b.status<>'pending' or b.slot<=now() or o.status<>'live' then raise exception 'booking cannot be confirmed'; end if;
  elsif p_status='cancelled' then
    if b.status='cancelled' then return; end if;
  else raise exception 'invalid booking transition'; end if;
  update bookings set status=p_status where id=b.id;
end;
$$ language plpgsql security definer set search_path=public;

-- A narrow grant list rather than PostgreSQL's default PUBLIC execution.
revoke execute on function get_my_profile(),select_account_type(text),submit_verification(text),claim_venue(uuid),
 request_join(uuid),approve_join_request(uuid),withdraw_join_request(uuid),decline_join_request(uuid),
 cancel_post(uuid),close_expired_posts(),change_booking_status(uuid,text),create_booking(uuid,timestamptz,int),
 get_or_create_conversation(uuid,uuid,uuid),list_my_conversations(),mark_conversation_read(uuid) from public,anon,authenticated;
grant execute on function get_my_profile(),select_account_type(text),submit_verification(text),claim_venue(uuid),
 request_join(uuid),approve_join_request(uuid),withdraw_join_request(uuid),decline_join_request(uuid),cancel_post(uuid),
 change_booking_status(uuid,text),create_booking(uuid,timestamptz,int),get_or_create_conversation(uuid,uuid,uuid),
 list_my_conversations(),mark_conversation_read(uuid) to authenticated;
grant execute on function close_expired_posts() to service_role;
revoke execute on function approved_join_count(uuid) from public;
grant execute on function approved_join_count(uuid) to anon,authenticated;
-- Notification contents are server-owned. The client can only mark read.
revoke update on notifications from anon,authenticated;
grant update(read_at) on notifications to authenticated;


-- 00012_booking_slots.sql
-- Stable business-defined slots. Legacy bookings stay intact and are backfilled.

alter table offers add column if not exists slot_minutes int not null default 60 check(slot_minutes between 15 and 480),
 add column if not exists resource_key text not null default 'default' check(char_length(btrim(resource_key)) between 1 and 80);
create table offer_slots(
 id uuid primary key default gen_random_uuid(),offer_id uuid not null references offers(id) on delete cascade,
 starts_at timestamptz not null,ends_at timestamptz not null,capacity int not null check(capacity between 1 and 500),
 check(ends_at>starts_at),unique(offer_id,starts_at)
);
alter table offer_slots enable row level security;
create policy "slots visible with offer" on offer_slots for select using(exists(
 select 1 from offers o where o.id=offer_id and (o.status='live' or o.business_id=auth.uid())
));
grant select on offer_slots to authenticated;
revoke insert,update,delete on offer_slots from anon,authenticated;
alter table bookings add column if not exists slot_id uuid references offer_slots(id),
 add column if not exists hold_expires_at timestamptz;
-- Preserve all legacy timestamps and seat allocations; do not delete history.
insert into offer_slots(offer_id,starts_at,ends_at,capacity)
select b.offer_id,b.slot,b.slot+make_interval(mins=>o.slot_minutes),greatest(o.slot_capacity,least(500,sum(b.party_size)::int))
from bookings b join offers o on o.id=b.offer_id group by b.offer_id,b.slot,o.slot_minutes,o.slot_capacity;
update bookings b set slot_id=s.id from offer_slots s where s.offer_id=b.offer_id and s.starts_at=b.slot;
-- Existing pending reservations remain held. Only new bookings get a timed hold.
create or replace function build_offer_slots() returns trigger as $$
begin
 if tg_op='UPDATE' and row(new.starts_at,new.ends_at,new.slot_capacity,new.slot_minutes) is not distinct from
   row(old.starts_at,old.ends_at,old.slot_capacity,old.slot_minutes) then return new; end if;
 if tg_op='UPDATE' then
   if exists(select 1 from bookings where offer_id=new.id) then raise exception 'cannot reschedule an offer with bookings'; end if;
   delete from offer_slots where offer_id=new.id;
 end if;
 insert into offer_slots(offer_id,starts_at,ends_at,capacity)
 select new.id,t,t+make_interval(mins=>new.slot_minutes),new.slot_capacity
 from generate_series(new.starts_at,new.ends_at-make_interval(mins=>new.slot_minutes),make_interval(mins=>new.slot_minutes)) t;
 return new;
end;
$$ language plpgsql security definer set search_path=public;
-- Generate regular slots only when they do not overlap a legacy slot.
insert into offer_slots(offer_id,starts_at,ends_at,capacity)
select o.id,t,t+make_interval(mins=>o.slot_minutes),o.slot_capacity from offers o
cross join lateral generate_series(o.starts_at,o.ends_at-make_interval(mins=>o.slot_minutes),make_interval(mins=>o.slot_minutes)) t
where not exists(select 1 from offer_slots s where s.offer_id=o.id and s.starts_at<t+make_interval(mins=>o.slot_minutes) and s.ends_at>t)
on conflict do nothing;
create trigger trg_build_offer_slots after insert or update on offers for each row execute function build_offer_slots();
create or replace function guard_offer_publish() returns trigger as $$
declare p profiles;
begin
 if tg_op='UPDATE' and new.business_id is distinct from old.business_id then raise exception 'offer ownership cannot change'; end if;
 if new.ends_at<=new.starts_at or new.slot_capacity not between 1 and 500 or
   new.ends_at-new.starts_at>interval '31 days' or char_length(btrim(new.title)) not between 4 and 80 or
   char_length(btrim(new.description)) not between 10 and 1000 then raise exception 'invalid offer details'; end if;
 select * into p from profiles where id=new.business_id for update;
 if p.account_type is distinct from 'business' or not p.onboarding_completed then raise exception 'business onboarding required'; end if;
 if new.status='live' and p.verification_status is distinct from 'verified' then raise exception 'only verified businesses can publish'; end if;
 if tg_op='INSERT' and new.starts_at<=now() then raise exception 'offer starts must be in the future'; end if;
 if tg_op='UPDATE' then
   if old.status in ('ended','cancelled') and new.status is distinct from old.status then raise exception 'ended offers cannot reopen'; end if;
   if old.status='live' and row(new.starts_at,new.ends_at,new.slot_capacity,new.slot_minutes,new.resource_key,new.venue_id) is distinct from
     row(old.starts_at,old.ends_at,old.slot_capacity,old.slot_minutes,old.resource_key,old.venue_id) then raise exception 'live slot details cannot change'; end if;
 end if;
 if new.status='live' and (tg_op='INSERT' or old.status<>'live') then
   if new.ends_at<=now() then raise exception 'offer expired'; end if;
   if exists(select 1 from offers o where o.id<>new.id and o.business_id=new.business_id and o.resource_key=new.resource_key
     and o.status='live' and o.starts_at<new.ends_at and o.ends_at>new.starts_at) then raise exception 'another live offer overlaps this resource'; end if;
 end if;
 return new;
end;
$$ language plpgsql security definer set search_path=public;
drop trigger if exists trg_guard_offer_publish on offers;
create trigger trg_guard_offer_publish before insert or update on offers for each row execute function guard_offer_publish();
-- Authenticated clients only change owner fields. Immutable ownership and counters.
revoke insert,update,delete on offers from anon,authenticated;
grant insert(business_id,title,description,discount_pct,price_cents,starts_at,ends_at,venue_id,slot_capacity,slot_minutes,resource_key,status),
 update(title,description,discount_pct,price_cents,starts_at,ends_at,venue_id,slot_capacity,slot_minutes,resource_key,status) on offers to authenticated;
create or replace function book_offer_slot(p_slot_id uuid,p_party_size int) returns json as $$
declare s offer_slots;o offers;bid uuid;oid uuid;taken int;booking_id uuid;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 if p_party_size is null or p_party_size not between 1 and 50 then raise exception 'invalid party size'; end if;
 if not exists(select 1 from profiles where id=auth.uid() and account_type='personal' and onboarding_completed) then raise exception 'personal onboarding required'; end if;
 select offer_id into oid from offer_slots where id=p_slot_id;
 select business_id into bid from offers where id=oid;
 -- Serialize every resource reservation at the business, then offer, slot, booking.
 perform 1 from profiles where id=bid for update;
 select * into o from offers where id=oid for update;
 select * into s from offer_slots where id=p_slot_id for update;
 if not found or o.status<>'live' or o.ends_at<=now() then raise exception 'offer is not live'; end if;
 if o.business_id=auth.uid() then raise exception 'cannot book your own offer'; end if;
 if s.starts_at<=now() then raise exception 'slot must be in the future'; end if;
 if s.starts_at<o.starts_at or s.ends_at>o.ends_at then raise exception 'slot outside offer window'; end if;
 if not exists(select 1 from profiles where id=bid and verification_status='verified') then raise exception 'business is not verified'; end if;
 -- Overlapping legacy offers on one resource cannot bypass the slot model.
 if exists(select 1 from bookings b join offers other on other.id=b.offer_id join offer_slots bs on bs.id=b.slot_id
   where other.business_id=bid and other.resource_key=o.resource_key and other.id<>o.id
     and b.status in ('pending','confirmed') and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())
     and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at) then raise exception 'resource already booked'; end if;
 select coalesce(sum(b.party_size),0) into taken from bookings b join offer_slots bs on bs.id=b.slot_id
 where b.offer_id=o.id and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at and b.status in ('pending','confirmed')
   and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now());
 if taken+p_party_size>s.capacity then raise exception 'not enough seats left for this slot'; end if;
 insert into bookings(offer_id,customer_id,slot_id,slot,party_size,status,hold_expires_at)
 values(o.id,auth.uid(),s.id,s.starts_at,p_party_size,'pending',least(now()+interval '30 minutes',s.starts_at)) returning id into booking_id;
 return json_build_object('booking_id',booking_id,'seats_left',s.capacity-taken-p_party_size);
end;
$$ language plpgsql security definer set search_path=public;
-- Keep the legacy function name, but require an exact registered slot.
create or replace function create_booking(p_offer_id uuid,p_slot timestamptz,p_party_size int) returns json as $$
declare sid uuid;
begin
 select id into sid from offer_slots where offer_id=p_offer_id and starts_at=p_slot;
 if sid is null then raise exception 'choose an available business-defined slot'; end if;
 return book_offer_slot(sid,p_party_size);
end;
$$ language plpgsql security definer set search_path=public;
create or replace function change_booking_status(p_booking_id uuid,p_status text) returns void as $$
declare b bookings;o offers;oid uuid;bid uuid;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 select offer_id into oid from bookings where id=p_booking_id;
 select business_id into bid from offers where id=oid;
 perform 1 from profiles where id=bid for update;
 select * into o from offers where id=oid for update;
 select * into b from bookings where id=p_booking_id for update;
 if not found or (b.customer_id is distinct from auth.uid() and o.business_id is distinct from auth.uid()) then raise exception 'not your booking'; end if;
 if p_status='confirmed' then
   if o.business_id is distinct from auth.uid() then raise exception 'only business can confirm'; end if;
   if b.status<>'pending' or b.slot<=now() or o.status<>'live' or (b.hold_expires_at is not null and b.hold_expires_at<=now()) then raise exception 'booking cannot be confirmed'; end if;
 elsif p_status='cancelled' then if b.status='cancelled' then return; end if;
 else raise exception 'invalid booking transition'; end if;
 update bookings set status=p_status where id=b.id;
end;
$$ language plpgsql security definer set search_path=public;
create or replace function available_offer_slots(p_offer_id uuid) returns jsonb as $$
 select coalesce(jsonb_agg(to_jsonb(t) order by t.starts_at),'[]'::jsonb) from (
  select s.id,s.starts_at,s.ends_at,s.capacity,greatest(0,s.capacity-coalesce((
   select sum(b.party_size)::int from bookings b join offer_slots bs on bs.id=b.slot_id where b.offer_id=s.offer_id
    and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at and b.status in ('pending','confirmed')
    and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())
  ),0)) as seats_left from offer_slots s join offers o on o.id=s.offer_id
  where s.offer_id=p_offer_id and s.starts_at>now() and (o.status='live' or o.business_id=auth.uid())
 )t;
$$ language sql stable security definer set search_path=public;
create or replace function expire_booking_holds() returns int as $$
declare n int;
begin
 update bookings set status='cancelled' where status='pending' and hold_expires_at<=now();
 get diagnostics n=row_count;return n;
end;
$$ language plpgsql security definer set search_path=public;
revoke execute on function book_offer_slot(uuid,int),available_offer_slots(uuid),expire_booking_holds() from public,anon,authenticated;
grant execute on function book_offer_slot(uuid,int),available_offer_slots(uuid) to authenticated;
grant execute on function expire_booking_holds() to service_role;


-- 00013_push_outbox.sql
-- Push delivery is driven by committed notification events, never client text.

create table push_jobs(
 id uuid primary key default gen_random_uuid(),notification_id uuid not null unique references notifications(id) on delete cascade,
 attempts int not null default 0,next_attempt_at timestamptz not null default now(),sent_at timestamptz,last_error text
);
alter table push_jobs enable row level security;
revoke all on push_jobs from anon,authenticated;
grant all on push_jobs to service_role;
create or replace function queue_notification_push() returns trigger as $$
begin insert into push_jobs(notification_id) values(new.id) on conflict do nothing;return new;end;
$$ language plpgsql security definer set search_path=public;
create trigger trg_queue_notification_push after insert on notifications for each row execute function queue_notification_push();
-- Bounded claims with leases prevent repeated worker runs from sending the same job concurrently.
create or replace function claim_push_jobs() returns jsonb as $$
 with jobs as (select id from push_jobs where sent_at is null and attempts<5 and next_attempt_at<=now()
  order by next_attempt_at for update skip locked limit 50),claimed as (
 update push_jobs j set attempts=j.attempts+1,next_attempt_at=now()+interval '5 minutes' from jobs where jobs.id=j.id
 returning j.id,j.notification_id
 ) select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'user_id',n.user_id,'title',n.title,'body',n.body)),'[]'::jsonb)
 from claimed c join notifications n on n.id=c.notification_id;
$$ language sql security definer set search_path=public;
-- One Expo token belongs to the account currently using its installation.
-- Keep the newest registration if an old version registered it to several users.
delete from push_tokens a using push_tokens b where a.token=b.token and
 (a.updated_at,a.user_id)<(b.updated_at,b.user_id);
create unique index push_token_installation_unique on push_tokens(token);
revoke insert,update on push_tokens from anon,authenticated;
create or replace function register_push_token(p_token text,p_platform text) returns void as $$
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 if p_token is null or p_token !~ '^(ExponentPushToken|ExpoPushToken)\[[A-Za-z0-9_-]+\]$'
 or p_platform is null or p_platform not in ('ios','android') then raise exception 'invalid push token'; end if;
 insert into push_tokens(user_id,token,platform,updated_at) values(auth.uid(),p_token,p_platform,now())
 on conflict(token) do update set user_id=excluded.user_id,platform=excluded.platform,updated_at=now();
end;
$$ language plpgsql security definer set search_path=public;
revoke execute on function claim_push_jobs(),register_push_token(text,text) from public,anon,authenticated;
grant execute on function claim_push_jobs() to service_role;
grant execute on function register_push_token(text,text) to authenticated;
-- Realtime changes must be explicitly published in Supabase.
do $$ declare t text;begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  foreach t in array array['posts','join_requests','offers','bookings','messages','notifications'] loop
   if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then
    execute format('alter publication supabase_realtime add table public.%I',t);
   end if;
  end loop;
 end if;
end;$$;


-- 00014_location.sql

create or replace function nearby_venues_with_distance(p_lat double precision,p_lng double precision,p_radius_m int)
returns jsonb as $$
begin
 if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180
  or p_radius_m is null or p_radius_m not between 100 and 50000 then raise exception 'invalid location or radius'; end if;
 return (select coalesce(jsonb_agg(to_jsonb(t) order by t.distance_m),'[]'::jsonb) from (
  select v.*,st_distance(v.location,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography) as distance_m from venues v
  where v.location is not null and st_dwithin(v.location,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography,p_radius_m)
 )t);
end;
$$ language plpgsql stable security invoker set search_path=public;
revoke execute on function nearby_venues_with_distance(double precision,double precision,int) from public;
grant execute on function nearby_venues_with_distance(double precision,double precision,int) to authenticated;
-- Refresh this view without changing existing column positions.
create or replace view business_bookings with (security_invoker=true) as
select b.id,b.offer_id,b.customer_id,b.slot,b.party_size,b.status,b.created_at,
 o.business_id,o.title as offer_title,c.display_name as customer_name,b.slot_id,b.hold_expires_at
from bookings b join offers o on o.id=b.offer_id join profiles c on c.id=b.customer_id;


-- 00015_profile_trigger_grants.sql
-- 00015: the guard_post_edit() trigger (00011) runs as the invoking
-- authenticated user and reads profiles.account_type + onboarding_completed,
-- but 00011 granted only (id, display_name, avatar_url, bio, business_name,
-- verification_status) -> post publish failed with
-- "permission denied for table profiles". Grant the two trigger columns.
grant select (account_type, onboarding_completed) on profiles to authenticated;


-- 00016_verification_review.sql
-- 00016 — Email review flow for business verification.
--
-- When a business submits a verification document (status -> 'pending'), a
-- trigger fires an HTTP call (pg_net, async background worker) to the
-- `notify-verification` edge function, which emails the admin the document
-- with one-click approve / reject-with-reason links.
--
-- Run this file in the Supabase dashboard SQL editor (one-shot paste).
-- The edge functions must be deployed separately (see supabase/functions/).

-- Rejection reason shown to the business in the app.
alter table profiles
  add column if not exists verification_note text;

-- Notification kinds for verification decisions (business gets an in-app
-- notification + push when the admin approves or rejects).
alter table notifications drop constraint if exists notifications_kind_check;
alter table notifications add constraint notifications_kind_check check (
  kind in (
    'join_request', 'request_approved', 'request_declined',
    'booking', 'booking_confirmed', 'booking_cancelled', 'message',
    'verification_approved', 'verification_rejected'
  )
);

-- Webhook trigger: status flips to 'pending' -> ping the edge function.
create or replace function notify_verification_pending()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.verification_status = 'pending'
     and old.verification_status is distinct from 'pending' then
    perform net.http_post(
      url := 'https://ggeejgykahzquynwighw.supabase.co/functions/v1/notify-verification',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object('user_id', new.id),
      timeout_milliseconds := 5000
    );
  end if;
  return new;
end;
$$;

drop trigger if exists trg_notify_verification_pending on profiles;
create trigger trg_notify_verification_pending
  after update of verification_status on profiles
  for each row
  execute function notify_verification_pending();


-- 00017_flow_integrity.sql
-- Forward-only fixes for live offer, booking, chat, and request flows.

-- Customers retain the public offer context associated with their own history.
-- Definer helper avoids a recursive offers -> bookings -> offers RLS policy.
create or replace function has_offer_booking(p_offer_id uuid) returns boolean as $$
 select exists(select 1 from bookings where offer_id=p_offer_id and customer_id=auth.uid());
$$ language sql stable security definer set search_path=public;
revoke all on function has_offer_booking(uuid) from public,anon;
grant execute on function has_offer_booking(uuid) to authenticated;
drop policy "offers read live" on offers;
create policy "offers read live" on offers for select using (
 status='live' and ends_at>now() and exists(select 1 from profiles p where p.id=business_id and p.verification_status='verified')
);
create policy "customers retain booked offer context" on offers for select to authenticated
 using (has_offer_booking(id));

-- Validate complete windows on the server as well as in the app.
create or replace function guard_offer_publish() returns trigger as $$
declare p profiles;
begin
 if tg_op='UPDATE' and new.business_id is distinct from old.business_id then raise exception 'offer ownership cannot change'; end if;
 -- Legacy malformed windows must still be cancellable without rewriting history.
 if tg_op='UPDATE' and new.status in ('ended','cancelled') and
  row(new.title,new.description,new.discount_pct,new.price_cents,new.starts_at,new.ends_at,new.slot_capacity,new.slot_minutes,new.resource_key,new.venue_id) is not distinct from
  row(old.title,old.description,old.discount_pct,old.price_cents,old.starts_at,old.ends_at,old.slot_capacity,old.slot_minutes,old.resource_key,old.venue_id) then return new; end if;
 if new.ends_at<=new.starts_at or new.ends_at-new.starts_at<make_interval(mins=>new.slot_minutes)
   or new.slot_capacity not between 1 and 500 or new.ends_at-new.starts_at>interval '31 days'
   or char_length(btrim(new.title)) not between 4 and 80
   or char_length(btrim(new.description)) not between 10 and 1000 then raise exception 'invalid offer details or booking window'; end if;
 select * into p from profiles where id=new.business_id for update;
 if p.account_type is distinct from 'business' or not p.onboarding_completed then raise exception 'business onboarding required'; end if;
 if tg_op='INSERT' and new.venue_id is null then
   select id into new.venue_id from venues where business_id=new.business_id order by created_at,id limit 1;
 end if;
 if new.venue_id is not null and not exists(select 1 from venues where id=new.venue_id and business_id=new.business_id) then
   raise exception 'choose a venue associated with your business';
 end if;
 if new.status='live' and p.verification_status is distinct from 'verified' then raise exception 'only verified businesses can publish'; end if;
 if tg_op='INSERT' and new.starts_at<=now() then raise exception 'offer starts must be in the future'; end if;
 if tg_op='UPDATE' then
   if old.status in ('ended','cancelled') and new.status is distinct from old.status then raise exception 'ended offers cannot reopen'; end if;
   if old.status='live' and new.status='draft' then raise exception 'a live offer must be cancelled rather than returned to draft'; end if;
   if old.status='live' and row(new.starts_at,new.ends_at,new.slot_capacity,new.slot_minutes,new.resource_key,new.venue_id) is distinct from
     row(old.starts_at,old.ends_at,old.slot_capacity,old.slot_minutes,old.resource_key,old.venue_id) then raise exception 'live slot details cannot change'; end if;
 end if;
 if new.status='live' and (tg_op='INSERT' or old.status<>'live') then
   if new.ends_at<=now() then raise exception 'offer expired'; end if;
   if exists(select 1 from offers o where o.id<>new.id and o.business_id=new.business_id and o.resource_key=new.resource_key
     and o.status='live' and o.ends_at>now() and o.starts_at<new.ends_at and o.ends_at>new.starts_at) then raise exception 'another live offer overlaps this resource'; end if;
 end if;
 return new;
end;
$$ language plpgsql security definer set search_path=public;

-- Updates use the same business -> offer lock order as reservations.
-- Revoking both table and column privileges closes the old direct-write path.
revoke update on offers from anon,authenticated;
revoke update(title,description,discount_pct,price_cents,starts_at,ends_at,venue_id,slot_capacity,slot_minutes,resource_key,status) on offers from anon,authenticated;
create or replace function update_offer(p_offer_id uuid,p_patch jsonb) returns jsonb as $$
declare o offers; p profiles;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' then raise exception 'invalid offer patch'; end if;
 if exists(select 1 from jsonb_object_keys(p_patch) k where k not in
  ('title','description','discount_pct','price_cents','starts_at','ends_at','venue_id','slot_capacity','slot_minutes','resource_key','status')) then raise exception 'protected offer field'; end if;
 select * into p from profiles where id=auth.uid() for update;
 select * into o from offers where id=p_offer_id and business_id=auth.uid() for update;
 if not found then raise exception 'offer not found or not yours'; end if;
 update offers set
 title=case when p_patch?'title' then btrim(p_patch->>'title') else title end,
 description=case when p_patch?'description' then btrim(p_patch->>'description') else description end,
 discount_pct=case when p_patch?'discount_pct' then (p_patch->>'discount_pct')::int else discount_pct end,
 price_cents=case when p_patch?'price_cents' then (p_patch->>'price_cents')::int else price_cents end,
 starts_at=case when p_patch?'starts_at' then (p_patch->>'starts_at')::timestamptz else starts_at end,
 ends_at=case when p_patch?'ends_at' then (p_patch->>'ends_at')::timestamptz else ends_at end,
 venue_id=case when p_patch?'venue_id' then (p_patch->>'venue_id')::uuid else venue_id end,
 slot_capacity=case when p_patch?'slot_capacity' then (p_patch->>'slot_capacity')::int else slot_capacity end,
 slot_minutes=case when p_patch?'slot_minutes' then (p_patch->>'slot_minutes')::int else slot_minutes end,
 resource_key=case when p_patch?'resource_key' then btrim(p_patch->>'resource_key') else resource_key end,
 status=case when p_patch?'status' then p_patch->>'status' else status end
 where id=o.id returning * into o;
 return to_jsonb(o)||jsonb_build_object('business',jsonb_build_object('display_name',coalesce(p.business_name,p.display_name)));
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function update_offer(uuid,jsonb) from public,anon;
grant execute on function update_offer(uuid,jsonb) to authenticated;

-- Ending an offer releases its future reservations and notifies customers.
create or replace function cancel_ended_offer_bookings() returns trigger as $$
begin
 if new.status in ('ended','cancelled') and old.status is distinct from new.status then
  update bookings set status='cancelled' where offer_id=new.id and
   (status='pending' or (status='confirmed' and slot>now()));
 end if;
 return new;
end;
$$ language plpgsql security definer set search_path=public;
create trigger trg_cancel_ended_offer_bookings after update of status on offers
 for each row execute function cancel_ended_offer_bookings();
update bookings b set status='cancelled' from offers o where b.offer_id=o.id and o.status='cancelled'
 and (b.status='pending' or (b.status='confirmed' and b.slot>now()));

create or replace function available_offer_slots(p_offer_id uuid) returns jsonb as $$
 select coalesce(jsonb_agg(to_jsonb(t) order by t.starts_at),'[]'::jsonb) from (
  select s.id,s.starts_at,s.ends_at,s.capacity,
   case when exists(select 1 from bookings b join offers other on other.id=b.offer_id join offer_slots bs on bs.id=b.slot_id
    where other.business_id=o.business_id and other.resource_key=o.resource_key and other.id<>o.id
     and b.status in ('pending','confirmed') and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())
     and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at) then 0
   else greatest(0,s.capacity-coalesce((select sum(b.party_size)::int from bookings b join offer_slots bs on bs.id=b.slot_id
    where b.offer_id=s.offer_id and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at and b.status in ('pending','confirmed')
     and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())),0)) end as seats_left
  from offer_slots s join offers o on o.id=s.offer_id
  where s.offer_id=p_offer_id and s.starts_at>now() and o.ends_at>now() and
   ((o.status='live' and exists(select 1 from profiles p where p.id=o.business_id and p.verification_status='verified'))
    or (o.business_id=auth.uid() and o.status='draft'))
 )t;
$$ language sql stable security definer set search_path=public;

-- Server-owned message chronology; only membership RPCs can write read cursors.
revoke insert on messages from anon,authenticated;
grant insert(conversation_id,sender_id,body) on messages to authenticated;
revoke insert,update,delete on conversation_reads from anon,authenticated;
alter table messages alter column created_at set default clock_timestamp();
alter table messages add constraint messages_nonblank check(char_length(btrim(body)) between 1 and 2000) not valid;
create or replace function mark_conversation_read(p_conversation_id uuid,p_last_message_id uuid) returns void as $$
declare read_through timestamptz;
begin
 if auth.uid() is null or not exists(select 1 from conversations where id=p_conversation_id and (user_a=auth.uid() or user_b=auth.uid())) then raise exception 'not a conversation member'; end if;
 if p_last_message_id is null then return; end if;
 select created_at into read_through from messages where id=p_last_message_id and conversation_id=p_conversation_id;
 if not found then raise exception 'message does not belong to this conversation'; end if;
 insert into conversation_reads(conversation_id,user_id,last_read_at) values(p_conversation_id,auth.uid(),read_through)
 on conflict(conversation_id,user_id) do update set last_read_at=greatest(conversation_reads.last_read_at,excluded.last_read_at);
end;
$$ language plpgsql security definer set search_path=public;
create or replace function mark_conversation_read(p_conversation_id uuid) returns void as $$
 select mark_conversation_read(p_conversation_id,(select id from messages where conversation_id=p_conversation_id order by created_at desc,id desc limit 1));
$$ language sql security definer set search_path=public;
revoke all on function mark_conversation_read(uuid,uuid) from public,anon;
grant execute on function mark_conversation_read(uuid,uuid) to authenticated;

-- Resubmissions reuse a request row, so notify on a transition back to pending.
create or replace function notify_join_request() returns trigger as $$
declare v_title text;v_body text;v_user uuid;v_kind text;
begin
 if tg_op='INSERT' or (tg_op='UPDATE' and new.status='pending' and old.status is distinct from 'pending') then
  v_kind:='join_request';
  select p.author_id,'New join request',pr.display_name||' wants to join "'||p.title||'"'
   into v_user,v_title,v_body from posts p join profiles pr on pr.id=new.requester_id where p.id=new.post_id;
 elsif new.status='approved' and old.status is distinct from 'approved' then
  v_kind:='request_approved';v_user:=new.requester_id;
  select 'Request approved','You''re in! "'||title||'"' into v_title,v_body from posts where id=new.post_id;
 elsif new.status='declined' and old.status is distinct from 'declined' then
  v_kind:='request_declined';v_user:=new.requester_id;
  select 'Request declined','"'||title||'" didn''t work out this time' into v_title,v_body from posts where id=new.post_id;
 else return new; end if;
 insert into notifications(user_id,kind,title,body,ref_id) values(v_user,v_kind,v_title,v_body,new.post_id);
 return new;
end;
$$ language plpgsql security definer set search_path=public;


-- 00018_verification_jobs.sql
-- Private, durable verification delivery and atomic reviews. No network extension required.

create table verification_review_jobs (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references profiles(id) on delete cascade,
 document_path text not null,
 created_at timestamptz not null default now(),
 attempts int not null default 0,
 next_attempt_at timestamptz not null default now(),
 sent_at timestamptz,
 last_error text,
 reviewed_at timestamptz,
 decision text check(decision in ('approved','rejected'))
);
alter table verification_review_jobs enable row level security;
revoke all on verification_review_jobs from public,anon,authenticated;
grant all on verification_review_jobs to service_role;
create index verification_jobs_delivery on verification_review_jobs(next_attempt_at) where sent_at is null and reviewed_at is null;

create or replace function clear_verification_note() returns trigger as $$
begin
 if new.verification_status='pending' and old.verification_status is distinct from 'pending' then new.verification_note:=null; end if;
 return new;
end;
$$ language plpgsql;
create trigger trg_clear_verification_note before update of verification_status on profiles
 for each row execute function clear_verification_note();

create or replace function notify_verification_pending() returns trigger as $$
begin
 if new.verification_status='pending' and (old.verification_status is distinct from 'pending' or old.verification_doc_path is distinct from new.verification_doc_path) then
  -- Supersede old links even if an administrator rejected outside the review RPC
  -- and the owner deliberately reuses the same storage path.
  update verification_review_jobs set reviewed_at=now() where user_id=new.id and reviewed_at is null;
  insert into verification_review_jobs(user_id,document_path) values(new.id,new.verification_doc_path);
 end if;
 return new;
end;
$$ language plpgsql security definer set search_path=public;
-- Any pending submissions predating this migration also need delivery.
insert into verification_review_jobs(user_id,document_path)
 select id,verification_doc_path from profiles where verification_status='pending' and verification_doc_path is not null;

create or replace function claim_verification_jobs() returns setof verification_review_jobs as $$
begin
 return query with due as (
  select j.id from verification_review_jobs j join profiles p on p.id=j.user_id
  where j.sent_at is null and j.reviewed_at is null and j.next_attempt_at<=now() and j.attempts<8
   and j.created_at>now()-interval '7 days'
   and p.verification_status='pending' and p.verification_doc_path=j.document_path
  order by j.created_at limit 10 for update of j skip locked
 ) update verification_review_jobs j set attempts=j.attempts+1,next_attempt_at=now()+interval '5 minutes'
 from due where j.id=due.id returning j.*;
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function claim_verification_jobs() from public,anon,authenticated;
grant execute on function claim_verification_jobs() to service_role;

create or replace function review_verification(p_review_id uuid,p_decision text,p_reason text default null) returns void as $$
declare j verification_review_jobs;p profiles; note text;
begin
 if p_decision is null or p_decision not in ('approved','rejected') or char_length(coalesce(p_reason,''))>200 then raise exception 'invalid decision';end if;
 select * into j from verification_review_jobs where id=p_review_id;
 if not found then raise exception 'review unavailable';end if;
 -- Match submit_verification's profile-first lock order.
 select * into p from profiles where id=j.user_id for update;
 select * into j from verification_review_jobs where id=p_review_id for update;
 if j.reviewed_at is not null or j.created_at<=now()-interval '7 days' or p.verification_status<>'pending'
   or p.verification_doc_path is distinct from j.document_path then raise exception 'review expired, stale, or already completed';end if;
 note:=case when p_decision='rejected' then coalesce(nullif(btrim(p_reason),''),'Please submit a clearer, valid business document.') else null end;
 update profiles set verification_status=case when p_decision='approved' then 'verified' else 'rejected' end,verification_note=note where id=p.id;
 update verification_review_jobs set reviewed_at=now(),decision=p_decision where id=j.id;
 insert into notifications(user_id,kind,title,body) values(p.id,
  case when p_decision='approved' then 'verification_approved' else 'verification_rejected' end,
  case when p_decision='approved' then 'Verification approved' else 'Verification needs attention' end,
  case when p_decision='approved' then 'Your business is verified. You can now publish offers.' else note end);
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function review_verification(uuid,text,text) from public,anon,authenticated;
grant execute on function review_verification(uuid,text,text) to service_role;


-- 00019_place_search_limits.sql
-- Server-only counters; no query text or coordinates are persisted.

create table place_search_usage (
 scope text not null,
 subject text not null,
 window_start timestamptz not null,
 requests int not null default 0,
 primary key(scope,subject,window_start)
);
create index place_search_usage_cleanup on place_search_usage(window_start);
alter table place_search_usage enable row level security;
revoke all on place_search_usage from public,anon,authenticated;
grant all on place_search_usage to service_role;
create function reserve_place_search(p_user_id uuid) returns boolean as $$
declare t timestamptz:=clock_timestamp();u text:=p_user_id::text;limits int[]:=array[2800,4,150,20];
 scopes text[]:=array['global_day','global_second','user_day','user_minute'];
 subjects text[]:=array['all','all',u,u];
 windows timestamptz[]:=array[date_trunc('day',t at time zone 'UTC') at time zone 'UTC',date_trunc('second',t),date_trunc('day',t at time zone 'UTC') at time zone 'UTC',date_trunc('minute',t)];
 i int;
begin
 if p_user_id is null or not exists(select 1 from profiles where id=p_user_id) then raise exception 'valid user required';end if;
 -- Tiny serialized transaction gives a hard shared ceiling across edge instances.
 perform pg_advisory_xact_lock(724193801);
 delete from place_search_usage where window_start<t-interval '2 days';
 for i in 1..4 loop
  if coalesce((select requests from place_search_usage where scope=scopes[i] and subject=subjects[i] and window_start=windows[i]),0)>=limits[i] then return false;end if;
 end loop;
 for i in 1..4 loop
  insert into place_search_usage(scope,subject,window_start,requests) values(scopes[i],subjects[i],windows[i],1)
   on conflict(scope,subject,window_start) do update set requests=place_search_usage.requests+1;
 end loop;
 return true;
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function reserve_place_search(uuid) from public,anon,authenticated;
grant execute on function reserve_place_search(uuid) to service_role;


-- 00020_offer_delete.sql
-- Draft-only hard delete for offers. Drafts with bookings must be cancelled, not deleted.

create or replace function delete_offer(p_offer_id uuid) returns void as $$
declare o offers;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 select * into o from offers where id = p_offer_id and business_id = auth.uid() for update;
 if not found then raise exception 'offer not found or not yours'; end if;
 if o.status <> 'draft' then raise exception 'only drafts can be deleted'; end if;
 if exists (select 1 from bookings where offer_id = o.id) then raise exception 'offer has bookings'; end if;
 delete from offer_slots where offer_id = o.id;
 delete from offers where id = o.id;
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function delete_offer(uuid) from public, anon;
grant execute on function delete_offer(uuid) to authenticated;


-- 00021_core_journeys.sql
-- Forward-only core journey fixes. Existing posts, bookings and messages remain intact.

alter table notifications drop constraint if exists notifications_kind_check;
alter table notifications add constraint notifications_kind_check check (kind in (
 'join_request','request_approved','request_declined','post_cancelled',
 'booking','booking_confirmed','booking_cancelled','message',
 'verification_approved','verification_rejected'
));

-- Tie new message notices to the actual message, not a transaction timestamp.
alter table notifications add column message_id uuid references messages(id) on delete set null;
create index notifications_unread_conversation_idx on notifications(user_id,ref_id)
 where kind='message' and read_at is null;
create or replace function notify_message() returns trigger as $$
declare recipient uuid; sender_name text;
begin
 select case when c.user_a=new.sender_id then c.user_b else c.user_a end
 into recipient from conversations c where c.id=new.conversation_id;
 select display_name into sender_name from profiles where id=new.sender_id;
 insert into notifications(user_id,kind,title,body,ref_id,message_id)
 values(recipient,'message','Message from '||coalesce(sender_name,'someone'),left(new.body,140),new.conversation_id,new.id);
 return new;
end;
$$ language plpgsql security definer set search_path=public;

create or replace function mark_conversation_read(p_conversation_id uuid,p_last_message_id uuid) returns void as $$
declare read_through timestamptz;
begin
 if auth.uid() is null or not exists(select 1 from conversations where id=p_conversation_id and (user_a=auth.uid() or user_b=auth.uid())) then
  raise exception 'not a conversation member';
 end if;
 select created_at into read_through from messages where id=p_last_message_id and conversation_id=p_conversation_id;
 if not found then
  if p_last_message_id is null then return; end if;
  raise exception 'message does not belong to this conversation';
 end if;
 insert into conversation_reads(conversation_id,user_id,last_read_at) values(p_conversation_id,auth.uid(),read_through)
 on conflict(conversation_id,user_id) do update set last_read_at=greatest(conversation_reads.last_read_at,excluded.last_read_at);
 update notifications n set read_at=clock_timestamp()
 where n.user_id=auth.uid() and n.kind='message' and n.ref_id=p_conversation_id and n.read_at is null and (
  exists(select 1 from messages m where m.id=n.message_id and m.conversation_id=p_conversation_id and m.created_at<=read_through)
  or (n.message_id is null and n.created_at<read_through)
 );
end;
$$ language plpgsql security definer set search_path=public;

-- One snapshot for badges; a chat message counts once even when it has a notice.
create or replace function unread_counts() returns jsonb as $$
 select jsonb_build_object(
  'messages',(select count(*) from messages m join conversations c on c.id=m.conversation_id
   left join conversation_reads r on r.conversation_id=c.id and r.user_id=auth.uid()
   where (c.user_a=auth.uid() or c.user_b=auth.uid()) and m.sender_id<>auth.uid()
   and m.created_at>coalesce(r.last_read_at,'1970-01-01'::timestamptz)),
  'notifications',(select count(*) from notifications where user_id=auth.uid() and read_at is null),
  'other_notifications',(select count(*) from notifications where user_id=auth.uid() and kind<>'message' and read_at is null)
 );
$$ language sql stable security definer set search_path=public;
revoke all on function unread_counts() from public,anon;
grant execute on function unread_counts() to authenticated;

-- Notify everyone affected by a host cancellation, including pending requests.
create or replace function notify_post_cancelled() returns trigger as $$
begin
 if new.status='cancelled' and old.status is distinct from new.status then
  insert into notifications(user_id,kind,title,body,ref_id)
  select requester_id,'post_cancelled','Plan cancelled','"'||new.title||'" was cancelled by the host',new.id
  from join_requests where post_id=new.id and status in ('pending','approved');
 end if;
 return new;
end;
$$ language plpgsql security definer set search_path=public;
create trigger trg_notify_post_cancelled after update of status on posts
 for each row execute function notify_post_cancelled();

-- Reservations are safe to retry when a mobile response is lost.
create or replace function book_offer_slot(p_slot_id uuid,p_party_size int) returns json as $$
declare s offer_slots;o offers;bid uuid;oid uuid;taken int;booking_id uuid; existing_id uuid; existing_party int;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 if p_party_size is null or p_party_size not between 1 and 50 then raise exception 'invalid party size'; end if;
 if not exists(select 1 from profiles where id=auth.uid() and account_type='personal' and onboarding_completed) then raise exception 'personal onboarding required'; end if;
 select offer_id into oid from offer_slots where id=p_slot_id;
 select business_id into bid from offers where id=oid;
 -- Serialize every resource reservation at the business, then offer, slot, booking.
 perform 1 from profiles where id=bid for update;
 select * into o from offers where id=oid for update;
 select * into s from offer_slots where id=p_slot_id for update;
 if not found or o.status<>'live' or o.ends_at<=now() then raise exception 'offer is not live'; end if;
 if o.business_id=auth.uid() then raise exception 'cannot book your own offer'; end if;
 if s.starts_at<=now() then raise exception 'slot must be in the future'; end if;
 if s.starts_at<o.starts_at or s.ends_at>o.ends_at then raise exception 'slot outside offer window'; end if;
 if not exists(select 1 from profiles where id=bid and verification_status='verified') then raise exception 'business is not verified'; end if;
 -- Overlapping legacy offers on one resource cannot bypass the slot model.
 if exists(select 1 from bookings b join offers other on other.id=b.offer_id join offer_slots bs on bs.id=b.slot_id
   where other.business_id=bid and other.resource_key=o.resource_key and other.id<>o.id
     and b.status in ('pending','confirmed') and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())
     and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at) then raise exception 'resource already booked'; end if;
 select coalesce(sum(b.party_size),0) into taken from bookings b join offer_slots bs on bs.id=b.slot_id
 where b.offer_id=o.id and bs.starts_at<s.ends_at and bs.ends_at>s.starts_at and b.status in ('pending','confirmed')
   and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now());
 -- A retry after a lost response returns the same active reservation.
 select b.id,b.party_size into existing_id,existing_party from bookings b
 where b.slot_id=s.id and b.customer_id=auth.uid() and b.status in ('pending','confirmed')
 and (b.status='confirmed' or b.hold_expires_at is null or b.hold_expires_at>now())
 order by b.created_at desc,b.id desc limit 1;
 if existing_id is not null then
  if existing_party<>p_party_size then raise exception 'You already requested this slot. Manage the existing booking in Activity.'; end if;
  return json_build_object('booking_id',existing_id,'seats_left',greatest(0,s.capacity-taken));
 end if;
 if taken+p_party_size>s.capacity then raise exception 'not enough seats left for this slot'; end if;
 insert into bookings(offer_id,customer_id,slot_id,slot,party_size,status,hold_expires_at)
 values(o.id,auth.uid(),s.id,s.starts_at,p_party_size,'pending',least(now()+interval '30 minutes',s.starts_at)) returning id into booking_id;
 return json_build_object('booking_id',booking_id,'seats_left',s.capacity-taken-p_party_size);
end;
$$ language plpgsql security definer set search_path=public;

-- A narrow delete path for empty posts. Preserve participation and chat history.
create or replace function delete_post(p_post_id uuid) returns void as $$
declare p posts;
begin
 if auth.uid() is null then raise exception 'not authenticated'; end if;
 select * into p from posts where id=p_post_id and author_id=auth.uid() for update;
 if not found then raise exception 'post not found or not yours'; end if;
 if exists(select 1 from join_requests where post_id=p.id) then
  raise exception 'This post has requests. Cancel it to retain participation history.';
 end if;
 delete from posts where id=p.id;
end;
$$ language plpgsql security definer set search_path=public;
revoke all on function delete_post(uuid) from public,anon;
grant execute on function delete_post(uuid) to authenticated;



-- 00021_profiles_posts_requests.sql
-- Migration 00021 — profile pictures, gender, request limits, slot-full status.
-- Run once in the Supabase dashboard SQL editor.

-- 1. Gender on profiles (personal accounts).
alter table public.profiles
  add column if not exists gender text check (gender in ('male', 'female', 'other'));
grant update (gender) on public.profiles to authenticated;

-- 2. Optional gender preference on posts.
alter table public.posts
  add column if not exists gender_preference text check (gender_preference in ('male', 'female', 'any'));
grant update (gender_preference) on public.posts to authenticated;

-- 3. Public avatars bucket.
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do nothing;

drop policy if exists "avatars public read" on storage.objects;
create policy "avatars public read" on storage.objects
  for select using (bucket_id = 'avatars');

drop policy if exists "avatars owner write" on storage.objects;
create policy "avatars owner write" on storage.objects
  for insert with check (
    bucket_id = 'avatars'
    and auth.uid()::text = (storage.foldername(name))[1]
  );

drop policy if exists "avatars owner update" on storage.objects;
create policy "avatars owner update" on storage.objects
  for update using (
    bucket_id = 'avatars'
    and auth.uid()::text = (storage.foldername(name))[1]
  );

drop policy if exists "avatars owner delete" on storage.objects;
create policy "avatars owner delete" on storage.objects
  for delete using (
    bucket_id = 'avatars'
    and auth.uid()::text = (storage.foldername(name))[1]
  );

-- 4. Decline counter for the 2-chance request limit.
alter table public.join_requests
  add column if not exists decline_count int not null default 0;

-- 5. New 'full' status: post filled before this request was handled.
alter table public.join_requests
  drop constraint if exists join_requests_status_check;
alter table public.join_requests
  add constraint join_requests_status_check
  check (status in ('pending', 'approved', 'declined', 'withdrawn', 'full'));

-- 6. Declining increments the counter.
create or replace function public.decline_join_request(p_request_id uuid)
returns void as $$
declare p posts; r join_requests; pid uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select post_id into pid from join_requests where id=p_request_id;
  select * into p from posts where id=pid for update;
  if not found or p.author_id is distinct from auth.uid() then raise exception 'only the host can decline'; end if;
  select * into r from join_requests where id=p_request_id for update;
  if not found or r.status <> 'pending' then raise exception 'request is not pending'; end if;
  update join_requests
    set status='declined', decline_count = decline_count + 1
  where id=r.id;
end;
$$ language plpgsql security definer set search_path = public;

-- 7. Block re-requests after 2 declines.
create or replace function public.request_join(p_post_id uuid)
returns jsonb as $$
declare p posts; r join_requests;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from profiles where id = auth.uid() and account_type = 'personal' and onboarding_completed) then raise exception 'personal onboarding required'; end if;
  select * into p from posts where id = p_post_id for update;
  if not found or p.author_id = auth.uid() then raise exception 'post not found or cannot join your own post'; end if;
  if p.status <> 'open' or coalesce(p.expires_at,p.starts_at) <= now() or p.starts_at <= now() then raise exception 'post is closed or expired'; end if;
  if (select count(*) from join_requests where post_id=p.id and status='approved') >= p.vacancies then raise exception 'post is full'; end if;
  select * into r from join_requests where post_id=p.id and requester_id=auth.uid() for update;
  if found and r.status in ('pending','approved') then raise exception 'you already requested or joined this post'; end if;
  if found and r.decline_count >= 2 then raise exception 'no more requests allowed for this post'; end if;
  if r.id is null then
    insert into join_requests(post_id,requester_id,status) values(p.id,auth.uid(),'pending') returning * into r;
  else
    -- Re-request after a decline/withdrawal: fresh row (new id) so the host
    -- is notified again, carrying the decline count forward.
    delete from join_requests where id=r.id;
    insert into join_requests(post_id,requester_id,status,decline_count)
      values(p.id,auth.uid(),'pending',r.decline_count) returning * into r;
  end if;
  return to_jsonb(r);
end;
$$ language plpgsql security definer set search_path = public;

-- 8. When a post fills, remaining pendings become 'full' (not 'declined').
create or replace function public.approve_join_request(p_request_id uuid)
returns json as $$
declare p posts; r join_requests; pid uuid; taken int;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select post_id into pid from join_requests where id=p_request_id;
  select * into p from posts where id=pid for update;
  if not found or p.author_id is distinct from auth.uid() then raise exception 'only the host can approve requests'; end if;
  select * into r from join_requests where id=p_request_id and post_id=p.id for update;
  if not found then raise exception 'join request not found'; end if;
  if r.status = 'full' then raise exception 'post is full'; end if;
  if r.status <> 'pending' then raise exception 'request is not pending'; end if;
  if r.requester_id=p.author_id then raise exception 'cannot join your own post'; end if;
  if p.status <> 'open' or coalesce(p.expires_at,p.starts_at)<=now() or p.starts_at<=now() then raise exception 'post is closed or expired'; end if;
  select count(*) into taken from join_requests where post_id=p.id and status='approved';
  if taken>=p.vacancies then raise exception 'post is full'; end if;
  update join_requests set status='approved' where id=r.id;
  if taken+1>=p.vacancies then
    update posts set status='closed' where id=p.id;
    update join_requests set status='full'
      where post_id=p.id and status='pending' and id<>r.id;
  end if;
  return json_build_object('spots_left',p.vacancies-taken-1,'post_closed',taken+1>=p.vacancies);
end;
$$ language plpgsql security definer set search_path = public;

-- 8b. When a post reopens, 'full' requests go back to 'pending'.
create or replace function public.reopen_post_if_space()
returns trigger as $$
declare p posts;
begin
  if old.status <> 'approved' then return coalesce(new,old); end if;
  if tg_op='UPDATE' and new.status='approved' then return new; end if;
  select * into p from posts where id=old.post_id for update;
  if p.status='closed' and coalesce(p.expires_at,p.starts_at)>now() and p.starts_at>now()
    and (select count(*) from join_requests where post_id=p.id and status='approved')<p.vacancies then
    update posts set status='open' where id=p.id;
    update join_requests set status='pending'
      where post_id=p.id and status='full';
  end if;
  return coalesce(new,old);
end;
$$ language plpgsql security definer set search_path = public;

-- 9. Notify on 'full' with slot-full copy (distinct from explicit declines).
-- Allow the new kind in the notifications check.
alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check check (kind in (
 'join_request','request_approved','request_declined','request_full','post_cancelled',
 'booking','booking_confirmed','booking_cancelled','message',
 'verification_approved','verification_rejected'
));

create or replace function public.notify_join_request()
returns trigger as $$
declare v_kind text; v_user uuid; v_title text; v_body text;
begin
  if tg_op = 'INSERT' then
    v_kind := 'join_request';
    select p.author_id into v_user from posts p where p.id = new.post_id;
    select 'New join request',
           pr.display_name || ' wants to join "' || p.title || '"'
      into v_title, v_body
    from profiles pr, posts p
    where pr.id = new.requester_id and p.id = new.post_id;
  elsif tg_op = 'UPDATE' and new.status = 'approved' and old.status is distinct from 'approved' then
    v_kind := 'request_approved';
    v_user := new.requester_id;
    select 'Request approved', 'You''re in! "' || p.title || '"'
      into v_title, v_body from posts p where p.id = new.post_id;
  elsif tg_op = 'UPDATE' and new.status = 'declined' and old.status is distinct from 'declined' then
    v_kind := 'request_declined';
    v_user := new.requester_id;
    select 'Request declined', '"' || p.title || '" didn''t work out this time'
      into v_title, v_body from posts p where p.id = new.post_id;
  elsif tg_op = 'UPDATE' and new.status = 'full' and old.status is distinct from 'full' then
    v_kind := 'request_full';
    v_user := new.requester_id;
    select 'Slot full', '"' || p.title || '" filled up before your request was handled'
      into v_title, v_body from posts p where p.id = new.post_id;
  else
    return new;
  end if;

  insert into notifications (user_id, kind, title, body, ref_id)
  values (v_user, v_kind, v_title, v_body, new.post_id);
  return new;
end;
$$ language plpgsql security definer set search_path = public;



commit;
